            aOrbiterF = ((aWandererG + RotL64(aIngress, 53U)) + 0x0785261106CC1343ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterD = ((aWandererJ + RotL64(aScatter, 23U)) + RotL64(aCarry, 43U)) + 0x755B07AFB602B4EEULL;
            aOrbiterK = ((aWandererI + RotL64(aCross, 48U)) + RotL64(aCarry, 13U)) + 0xFD144DEBE1A99E99ULL;
            aOrbiterC = (((aWandererK + RotL64(aIngress, 5U)) + RotL64(aCarry, 5U)) + 0x3C38E64CF6713FA7ULL) + aTwistOrbiterAssignSaltE[((aIndex + 11U)) & S_SALT1];
