            aOrbiterD = (((aWandererF + RotL64(aIngress, 18U)) + RotL64(aCarry, 11U)) + 0x6369D138308154BFULL) + aKeyRotateAOrbiterAssignSaltE[((aIndex + 24U)) & S_SALT1];
