            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x5F0DD1793D92C4BEULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterF) ^ 0x7CEACF4AC27DF140ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x8EABF4A513CB6757ULL), 43U);
