            aOrbiterD = ((aOrbiterD + aOrbiterA) + 0x915094E18C418C11ULL) + aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterD) ^ 0x1CD8B306854A0DE6ULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 17U)) & S_SALT1];
