            aWandererC = aWandererC + (((RotL64(aScatter, 51U) + aOrbiterI) + RotL64(aOrbiterA, 51U)) + aKeyRotateAWandererUpdateSaltA[(((31U - aIndex) + 19U)) & S_SALT1]);
