            aOrbiterG = ((aOrbiterG + aOrbiterK) + 0xDE706690D7523F52ULL) + aKeyRotateAOrbiterUpdateSaltA[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterI = ((aOrbiterI ^ aOrbiterG) ^ 0x5A959597AF80BBEFULL) ^ aKeyRotateAOrbiterUpdateSaltF[((aIndex + 7U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0x226F8F70377A255BULL), 3U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0xE52E27CF17340DE2ULL;
