            aWandererD = aWandererD + (((RotL64(aPrevious, 47U) + RotL64(aOrbiterD, 39U)) + aOrbiterJ) + RotL64(aCarry, 43U));
            aWandererJ = aWandererJ ^ (((RotL64(aIngress, 60U) + RotL64(aOrbiterG, 43U)) + aOrbiterC) + aKeyRotateAWandererUpdateSaltC[((aIndex + 19U)) & S_SALT1]);
