            aWandererG = aWandererG ^ ((RotL64(aScatter, 19U) + aOrbiterA) + RotL64(aOrbiterH, 29U));
            aWandererK = aWandererK + ((RotL64(aPrevious, 53U) + aOrbiterA) + RotL64(aOrbiterJ, 12U));
            aWandererF = aWandererF ^ ((RotL64(aCross, 58U) + RotL64(aOrbiterK, 21U)) + aOrbiterA);
            aWandererI = aWandererI + ((RotL64(aScatter, 37U) + RotL64(aOrbiterI, 53U)) + aOrbiterF);
            aWandererA = aWandererA ^ ((RotL64(aIngress, 29U) + aOrbiterI) + RotL64(aOrbiterC, 57U));
            aWandererC = aWandererC + ((RotL64(aCross, 43U) + RotL64(aOrbiterG, 46U)) + aOrbiterK);
            aWandererH = aWandererH ^ ((RotL64(aScatter, 5U) + RotL64(aOrbiterB, 3U)) + aOrbiterE);
            aWandererB = aWandererB + ((RotL64(aIngress, 41U) + RotL64(aOrbiterF, 27U)) + aOrbiterH);
