            //
            aScatter = (RotL64(aPrevious, 11U) ^ RotL64(aCross, 60U)) + (RotL64(aIngress, 41U) + RotL64(aCarry, 27U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterA = (aWandererD + RotL64(aPrevious, 47U)) + 0x4F79863BD2297E75ULL;
            aOrbiterI = ((aWandererF + RotL64(aIngress, 27U)) + 0x1EB311AB44DCBD99ULL) + aKeyRotateAOrbiterAssignSaltB[((aIndex + 18U)) & S_SALT1];
            aOrbiterJ = ((aWandererI + RotL64(aCross, 41U)) + RotL64(aCarry, 27U)) + 0x2258FE40D6202B60ULL;
            aOrbiterB = ((aWandererB + RotL64(aScatter, 53U)) + 0xA82271C10E7F2BF0ULL) + aKeyRotateAOrbiterAssignSaltA[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterC = ((aWandererK + RotL64(aIngress, 5U)) + RotL64(aCarry, 5U)) + 0x778E5146E3B4F06AULL;
            aOrbiterF = ((aWandererE + RotL64(aPrevious, 20U)) + RotL64(aCarry, 53U)) + 0xAD40B1E2634984D8ULL;
            aOrbiterH = (aWandererC + RotL64(aScatter, 11U)) + 0x43086539B3C068DFULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0x9032158782A20878ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0xA65452793655B8A6ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x13A6E45B407D6EEBULL), 57U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x6BAB1A6FAC2119CCULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterB) ^ 0xB4B85CE190E3BD1BULL) ^ aKeyRotateAOrbiterUpdateSaltC[((aIndex + 26U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xE829AD71E9D11057ULL), 51U);
