            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0xB1E13C78DAA35A84ULL;
            aOrbiterC = ((aOrbiterC ^ aOrbiterJ) ^ 0xF56C5732F1123422ULL) ^ aKeyRotateAOrbiterUpdateSaltF[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0xD9E83116DC34BBEFULL), 29U);
