            aOrbiterH = RotL64((aOrbiterH * 0x77C44498A9C921F1ULL), 43U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterJ) + 0x59EC69CDF1434DC3ULL) + aKeyRotateAOrbiterUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0xE8EC641B939D24EFULL;
            aOrbiterB = RotL64((aOrbiterB * 0x3FA6630F1B50614BULL), 35U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterH) + 0xC0EF27C371568295ULL) + aKeyRotateAOrbiterUpdateSaltD[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0xF399AEEA2697422EULL;
            aOrbiterF = RotL64((aOrbiterF * 0x345EE1687D028E73ULL), 5U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0xDE2BE3347D18FEB2ULL;
