            //
            aWandererC = aWandererC ^ ((RotL64(aIngress, 51U) + aOrbiterJ) + RotL64(aOrbiterC, 41U));
            aWandererI = aWandererI + (((RotL64(aPrevious, 3U) + RotL64(aOrbiterC, 57U)) + aOrbiterH) + RotL64(aCarry, 53U));
            aWandererB = aWandererB ^ (((RotL64(aCross, 10U) + aOrbiterF) + RotL64(aOrbiterJ, 35U)) + aKeyRotateAWandererUpdateSaltB[((aIndex + 10U)) & S_SALT1]);
