            //
            aIngress = (RotL64(aFuseLaneB[((aIndex + 17529U)) & S_BLOCK1], 21U) ^ RotL64(aWindLaneD[((aIndex + 21970U)) & S_BLOCK1], 38U));
            aIngress ^= (RotL64(aKeyRowReadA[((aIndex + 19744U)) & W_KEY1], 29U) ^ RotL64(aShadowLaneA[((aIndex + 23204U)) & S_BLOCK1], 3U));
            aIngress = TwistMix64::DiffuseB((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 21758U)) & S_BLOCK1], 41U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 23010U)) & S_BLOCK1], 3U));
            aCross ^= (RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 18514U)) & S_BLOCK1], 12U) ^ RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 20716U)) & S_BLOCK1], 29U));
            aCross = TwistMix64::DiffuseA((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aCross, 57U) ^ RotL64(aIngress, 11U)) + (RotL64(aPrevious, 23U) + RotL64(aCarry, 38U));
            aScatter = TwistMix64::DiffuseC((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterF = ((aWandererD + RotL64(aIngress, 21U)) + 0x9A455771CB949C11ULL) + aKeyRotateAOrbiterAssignSaltC[(((31U - aIndex) + 22U)) & S_SALT1];
            aOrbiterK = ((aWandererG + RotL64(aPrevious, 53U)) + RotL64(aCarry, 37U)) + 0x48509BC3BEE25B18ULL;
            aOrbiterA = ((aWandererK + RotL64(aCross, 12U)) + RotL64(aCarry, 57U)) + 0x25645DC6455C449CULL;
            aOrbiterH = ((aWandererH + RotL64(aScatter, 47U)) + RotL64(aCarry, 19U)) + 0x081B89DAD6DF1C3FULL;
            aOrbiterJ = ((aWandererB + RotL64(aIngress, 29U)) + 0x2FBD76BE31F7BF22ULL) + aKeyRotateAOrbiterAssignSaltE[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterD = (aWandererE + RotL64(aScatter, 39U)) + 0x521A9550BDFC1711ULL;
            aOrbiterB = (aWandererI + RotL64(aPrevious, 3U)) + 0x98FD9428F83F6456ULL;
            //
            aOrbiterF = ((aOrbiterF + aOrbiterK) + 0x20CE72B4F7EBEF2FULL) + aKeyRotateAOrbiterUpdateSaltC[(((31U - aIndex) + 21U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x7875AF9723D6A8A3ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x4437E2404924CE0DULL), 11U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x670ABCD1EE25CA78ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0x758147DD855B327DULL;
            aOrbiterK = RotL64((aOrbiterK * 0xE2EC1A0C6534A7EDULL), 29U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterH) + 0x6832047C8EE2E4B6ULL) + aKeyRotateAOrbiterUpdateSaltB[((aIndex + 27U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0x78AF4983D2E03491ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xF35909589AE36389ULL), 47U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterA) + 0x731AC246B08AA098ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterK) ^ 0x65AACF56782719A0ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x2F574CE53A1D9289ULL), 53U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x86501B28B51D8126ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterA) ^ 0x76B0486430DA3253ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x58662095F5247AE9ULL), 23U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0xBE16469328BA1264ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0x96D4FE13F6DFB0C1ULL) ^ aKeyRotateAOrbiterUpdateSaltE[((aIndex + 10U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xCB88AD0F6127E80DULL), 41U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0x180E61C9E860362BULL) + aKeyRotateAOrbiterUpdateSaltD[((aIndex + 9U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterD) ^ 0xECB19A33489917CFULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x25C846B22CFD663FULL), 5U);
            //
            aIngress = RotL64(aOrbiterB, 11U) ^ aOrbiterK;
            aIngress = aIngress + (aOrbiterH ^ RotL64(aOrbiterD, 47U));
            aIngress = aIngress + (RotL64(aOrbiterA, 19U) ^ aOrbiterF);
            aIngress = aIngress + RotL64(aOrbiterJ, 60U);
            aIngress = TwistMix64::DiffuseC((aIngress + aScatter));
            //
            aWandererD = aWandererD ^ ((RotL64(aCross, 57U) + aOrbiterH) + RotL64(aOrbiterK, 5U));
