            aWandererH = aWandererH ^ ((RotL64(aScatter, 34U) + RotL64(aOrbiterJ, 39U)) + aOrbiterB);
            aWandererE = aWandererE + ((((RotL64(aPrevious, 41U) + RotL64(aOrbiterF, 29U)) + aOrbiterA) + RotL64(aCarry, 41U)) + aKeyRotateAWandererUpdateSaltD[((aIndex + 23U)) & S_SALT1]);
            aWandererG = aWandererG ^ (((RotL64(aScatter, 3U) + RotL64(aOrbiterB, 46U)) + aOrbiterD) + aKeyRotateAWandererUpdateSaltC[(((31U - aIndex) + 5U)) & S_SALT1]);
            aWandererI = aWandererI + (((RotL64(aIngress, 21U) + aOrbiterF) + RotL64(aOrbiterH, 53U)) + RotL64(aCarry, 57U));
            aWandererK = aWandererK ^ ((RotL64(aCross, 27U) + RotL64(aOrbiterK, 13U)) + aOrbiterD);
