            aWandererD = aWandererD ^ (((RotL64(aPrevious, 23U) + RotL64(aOrbiterA, 47U)) + aOrbiterF) + aKeyRotateAWandererUpdateSaltD[(((31U - aIndex) + 23U)) & S_SALT1]);
