            aOrbiterJ = ((aOrbiterJ ^ aOrbiterF) ^ 0x7C5BEE59A63B0316ULL) ^ aKeyRotateAOrbiterUpdateSaltE[(((31U - aIndex) + 27U)) & S_SALT1];
